      "wallText": "站立、坐下、招手，接着是承重、蓄势、相拥、休息与等待。九项Blender研究共用角色的基本轮廓，分别改变姿态、材质和周围器物。本馆将它们作为一件组作观看；每项研究仍保留原来的页面、解读和附加角度。",
