      "wallText": "金框里九张几乎相同的脸，把奶蛙留在一道空白方框前。它抬起手，却没有碰到铜牌；最下排中间的肖像悄悄转身。我把熟悉的验证动作移进端正的展厅，让识别变成一场没有出口的礼仪：它越能认出同类，就越无法证明自己不是其中之一。",
