      "title": "水走以后",
      "titleEn": "After the Water Left",
      "year": "2026",
      "medium": "AI 辅助图像 · 干性蛋彩与油画质感",
      "type": "image",
      "alt": "灰绿瓷砖铺满干燥的废弃浅水池，三道同心波纹使完整地面平缓起伏；一只黄色梨形奶蛙双手垂下，静立左侧远处，前景散有枯叶。",
      "wallText": "池底早已干透，灰尘、裂纹和枯叶把这件事说得很清楚。但三圈涟漪仍从瓷砖内部缓慢展开：方格没有断裂，坚硬也没有被取消。奶蛙站在远处，不制造波纹，也不解释它。水已经走了，留下的地面却迟迟没有学会静止。",
