      "wallText": "盘子从正上方被看见，椅子坚持侧面，桌角却朝另一个方向倾斜。它们都像在等待一顿午餐，只是没有同意在同一个空间里发生。奶蛙安稳地坐着，两只脚越过照片的边缘，落进没有地面的蓝色。身体仍然完整，散掉的是让大家坐到一起的世界。",
