        "笑点落在奶蛙手中那枚小塞子上。它与海岸的尺度完全不相配，却仿佛足以控制整片潮汐。滴水、湿脚印和毫不惊讶的表情，把异常处理成了一件普通家务。",
        "奶蛙之眼的环形关系与黄、青绿、黑的顺序得到保留；青绿色在这里向海水的蓝绿方向偏移，细边转为浪沫和盐线。作品以原创构图模拟水粉与油彩肌理，不对应某件历史名画，也不展示真实排水装置。"
