      "number": "S01",
      "title": "站立：尚未发生什么",
      "titleEn": "Standing, Before Anything Happens",
      "year": "2026",
      "medium": "Blender 三维角色研究 · 数字材质与渲染",
      "type": "3d",
      "alt": "黄色梨形奶蛙在浅色摄影棚中站立，两臂下垂，奶油色圆腹正对观者。",
      "wallText": "它站着，什么也没发生。圆腹占据中心，手臂顺着身体垂落，浅色地面没有给出剧情。这副过于稳定的形象像一个尚未填写状态的头像：任何情绪都能投到它身上，角色本身只提供最低限度的回应。后面的变形，都从这一份平静开始。",
      "id": "baseline-neutral",
      "completionStatus": "completed",
      "interpretation": [
        "连续的头身轮廓没有独立脖颈，浅绿眼圈、黑瞳和短嘴被压缩成少量识别信号。宽腹与较窄的下肢构成上重下轻的体量，橄榄色手足则把末端清楚地收住。摄影棚的软影确认它有体积，又尽量不让环境替它讲故事。",
        "这是后续作品的形体基准，不引用某件历史雕塑。我把它读作一种可被重复使用的空白姿态：互联网头像经常无需改变五官，就能靠语境从礼貌变成敷衍，从可爱变成不合时宜。Blender 模型把这种稳定性写进可检查的形状和颜色，而不只保存在一张图里。此时的荒诞很轻，它来自观看者已经想替一具站立的身体安排意义。"
      ],
      "tags": [
        "基础姿势",
        "空白头像",
        "角色语法"
      ],
      "source": {},
