      "number": "S03",
      "title": "招手：一个尚未发送的你好",
      "titleEn": "A Wave, Before Hello",
      "year": "2026",
      "medium": "Blender 三维姿势研究 · 数字材质与渲染",
      "type": "3d",
      "alt": "奶蛙两脚分开站稳，一手抬起张开手掌，另一手停在腰腹侧。",
      "wallText": "一只手抬起来，整个身体就从“在这里”变成“对你在这里”。外开的双腿给招呼一个稳定支点，静止的手掌把问候留在半空。它可以是欢迎，也可以是告别；没有收件人和文字，最普通的社交手势反而暂时失去了用途。",
      "id": "baseline-wave",
      "completionStatus": "completed",
      "interpretation": [
        "抬臂打破基础站姿的左右平衡，另一侧手臂与分开的腿重新分配视觉重量。张开的手掌与圆腹之间留出空隙，使招手轮廓在小尺寸下依然清楚。面部几乎不增加表演，礼貌主要交给身体方向来完成。",
        "这是一个独立的静态姿势，后来才成为七秒循环的基础。单看这一刻，手势没有明确的开始和结束，观看者需要替它补出时间和对象。我把它读成尚未发送的“你好”：信息已经准备好，但它究竟面向谁仍然空缺。它与互联网欢迎图标共享一种简短的亲和力；将其郑重摆进展厅，会让日常界面的礼貌变得稍稍陌生。"
      ],
