      "wallText": "青瓷釉和端正的灯光把它请进雕塑的位置，它却将手肘交给矮枕，把另一只手留在肚子上。斜卧的身体拒绝起身，圆眼仍照常面对观者。作品已经准备好接受观看，角色退出了“应该做点什么”的姿势：博物馆照常开放，奶蛙本人午后不营业。",
