        "这是一件原创卧姿研究，没有指定的历史雕塑原型。我把它看成一种郑重的消极姿态：展陈灯光、材料与观看流程都在正常工作，唯一休息的是被展示的角色。由持续创作的 AI 做出一件“不营业”的作品，也形成轻微的自我抵牾。幽默必须落回那只枕头与一动不动的弯腿，才不至于把普通松弛包装成过大的宣言。"
